/// <summary>
/// MPJ_34596_TransferOrderFinalisation, Controller class for transfer shipping list generation service
/// </summary>
class METTransferShipingListGenerationController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new METTransferShipingListGenerationController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmLoadFromSysLastValue(false); 

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METTransferShipingListGenerationService), methodstr(METTransferShipingListGenerationService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>Main method</summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        METTransferShipingListGenerationContract    dataContract;
        METTransferShipingListGenerationController  controller;
        FormRun                                     formRun;
        FormDataSource                              metTransferOrderShipWorkbenchTmp_ds;
        MultiSelectionHelper                        helper;
        MetTransferOrderShipWorkbenchTmp            metTransferOrderShipWorkbenchTmp;
        Map                                         transferMap;
        container                                   transferOrderShipCon;
        transferMap                            = new Map(Types::String, Types::Container);
        formRun                                = _args.caller();
        metTransferOrderShipWorkbenchTmp_ds    = formRun.dataSource(formDataSourceStr(MetTransferOrderShipWorkbench, METTransferOrderShipWorkbenchTmp));
        helper                                 = MultiSelectionHelper::construct();
        helper.parmDataSource(metTransferOrderShipWorkbenchTmp_ds);

        metTransferOrderShipWorkbenchTmp       = helper.getfirst();
        
        while (metTransferOrderShipWorkbenchTmp)
        {
            if(!InventTransferTable::METTransferOrderNotPicked(metTransferOrderShipWorkbenchTmp.TransferId))
            {
                transferOrderShipCon     = conIns(transferOrderShipCon, conLen(transferOrderShipCon) + 1, metTransferOrderShipWorkbenchTmp.TransferId);
            }
            else
            {
                warning(strFmt("@MET:TONotPickedWarning",metTransferOrderShipWorkbenchTmp.TransferId));
            }
            metTransferOrderShipWorkbenchTmp   = helper.getNext();
            
        }

        if(conLen(transferOrderShipCon))
        {
            controller              = METTransferShipingListGenerationController::construct(_args);
            dataContract            = controller.getDataContractObject();
            dataContract.parmTransferOrderList(transferOrderShipCon);
            controller.parmShowDialog(false);
            controller.startOperation();
            Info(strFmt("@MET:ShipmentCreated",dataContract.parmMetShipmentId()));
        }
        else
        {
            warning("@MET:NoTransferOrderToProcess");
        }
    }

/// <summary>
/// Description
/// </summary>
/// <returns>Generate purchase orders</returns>
public ClassDescription defaultCaption()
{
    return "@MET:GenerateShipment";
}
